const calendar = $('Sheets — Calendrier').all().map(i => i.json);
const interactions = $('Sheets — Interactions').all().map(i => i.json);

// Filter to last 7 days
const weekAgo = new Date(Date.now() - 7 * 86400000).toISOString().split('T')[0];
const weekPosts = calendar.filter(c => c.Date >= weekAgo);
const weekInteractions = interactions.filter(i => i.Date >= weekAgo);

const stats = {
  total_posts_planned: weekPosts.length,
  total_posts_published: weekPosts.filter(p => p.Status_Publication === 'publié').length,
  total_interactions: weekInteractions.length,
  sentiment_breakdown: {
    positif: weekInteractions.filter(i => i.Sentiment === 'positif').length,
    negatif: weekInteractions.filter(i => i.Sentiment === 'négatif').length,
    neutre: weekInteractions.filter(i => i.Sentiment === 'neutre').length,
    question: weekInteractions.filter(i => i.Sentiment === 'question').length
  },
  networks_breakdown: {},
  posts_by_status: {
    published: weekPosts.filter(p => p.Status_Publication === 'publié').length,
    pending: weekPosts.filter(p => p.Status_Publication === 'planifié').length,
    produced: weekPosts.filter(p => p.Status_Contenu === 'produit').length
  }
};

// Count by network
for (const p of weekPosts) {
  const net = p.Reseau || 'unknown';
  stats.networks_breakdown[net] = (stats.networks_breakdown[net] || 0) + 1;
}

return [{ json: { stats, week_posts: weekPosts, week_interactions: weekInteractions, period: `${weekAgo} — ${new Date().toISOString().split('T')[0]}` } }];

