const response = $input.first().json;
const stats = $('Compile — Statistiques').first().json;

let report;
try {
  const text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  report = JSON.parse(text);
} catch (e) {
  report = { summary: 'Erreur génération du rapport', score_global: 0, highlights: [], improvements: [], recommendations: [] };
}

const weekNum = Math.ceil((new Date().getTime() - new Date(new Date().getFullYear(), 0, 1).getTime()) / (7 * 86400000));

return [{
  json: {
    Semaine: `S${weekNum}`,
    Score: report.score_global,
    Reach: stats.stats.total_posts_published,
    Engagement: stats.stats.total_interactions,
    Top_Posts: (report.highlights || []).join(' | '),
    Recommandations: (report.recommendations || []).map(r => r.action).join(' | '),
    report_full: report,
    period: stats.period
  }
}];
